// src/app/auth.interceptor.ts
var authInterceptor = (req, next) => {
  const auth = inject2(AuthService);
  const token = auth.token();
  const headers = {
    "X-Tenant-Id": currentTenantId()
  };
  if (token) {
    headers["Authorization"] = `Bearer ${token}`;
  }
  return next(req.clone({ setHeaders: headers }));
};

// src/app/api-busy.interceptor.ts
var silentUrlParts = ["/media/watch-events"];
var apiBusyInterceptor = (req, next) => {
  if (silentUrlParts.some((part) => req.url.includes(part))) {
    return next(req);
  }
  const busy = inject2(ApiBusyService);
  busy.begin();
  return next(req).pipe(finalize(() => busy.end()));
};

// src/app/app.config.ts
var appConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideZoneChangeDetection({ eventCoalescing: true }),
    provideHttpClient(withInterceptors([authInterceptor, apiBusyInterceptor])),
    provideRouter(routes)
  ]
};

